// Experimental exclusions selected on the supplied 257-signal sample. No future-success guarantee.
export const EXCLUSION_GROUPS=Object.freeze([{"side":"SHORT","conditions":[["rsi",">=",70],["closepos","<=",0.1]]},{"side":"LONG","conditions":[["atr",">=",4],["bbpos","<=",1]]},{"side":"LONG","conditions":[["btc50","<=",5],["btc7",">=",10]]},{"side":"SHORT","conditions":[["range",">=",35],["mfi","<=",85],["wick","<=",0.1]]},{"side":"LONG","conditions":[["vol","<=",4.5],["btc7","<=",5],["entryTrend",">=",2.5]]},{"side":"LONG","conditions":[["atr","<=",2.5],["vol","<=",3],["btc200","<=",7.5]]},{"side":"SHORT","conditions":[["atr","<=",4],["vol","<=",2],["slope",">=",2]]},{"side":"SHORT","conditions":[["atr","<=",4],["rsi",">=",75],["cmf","<=",0]]},{"side":"SHORT","conditions":[["range",">=",25],["stoch",">=",95],["bbwidth","<=",20]]},{"side":"SHORT","conditions":[["vol",">=",3],["slope",">=",1],["entryTrend","<=",1.5]]}]);
export const EXCLUSION_TEXT='Experimental X10 exclusions after the original entry rule. A group matches only for its side and when ALL its conditions hold; ANY matched group excludes. Uses closed pre-entry indicators only. Normalized conditions: '+JSON.stringify(EXCLUSION_GROUPS)+'. Selected on all257 historical signals:215TP retained,35of42TIMEOUT excluded,7remain. Not independent validation; zero future TP loss is not established.';
export function exclusionFeatures(t){
 const f=t.entryFeatures||{},b=t.benchmarkFeatures||{},sh=t.side==='SHORT',sign=sh?-1:1;
 const num=Number.isFinite,n=x=>num(x)?sh?100-x:x:null,sg=x=>num(x)?sign*x:null;
 const known=num(f.referenceClosedAt)&&num(t.entryTime)&&f.referenceClosedAt<=t.entryTime;
 if(!known)return null;
 const btcKnown=num(b.referenceClosedAt)&&b.referenceClosedAt<=t.entryTime;
 return {atr:f.atrPct,range:f.range20Pct,vol:f.volumeRatio20,rsi:n(f.rsi14),stoch:n(f.stochastic14K),mfi:n(f.moneyFlowIndex14),cmf:sg(f.chaikinMoneyFlow20),ma50dist:sg(f.closeDistanceSma50Pct),slope:sg(f.sma50Slope5Pct),wick:sh?f.lowerWickFraction:f.upperWickFraction,closepos:num(f.closePosition)?sh?1-f.closePosition:f.closePosition:null,bbpos:num(f.bollingerPosition)?sh?1-f.bollingerPosition:f.bollingerPosition:null,bbwidth:f.bollingerWidthPct,btc200:btcKnown?sg(b.closeDistanceSma200Pct):null,btc50:btcKnown?sg(b.closeDistanceSma50Pct):null,btcSlope:btcKnown?sg(b.sma50Slope5Pct):null,btc7:btcKnown?sg(b.return7dPct):null,entryTrend:sg(f.entryDistanceTrendPct)};
}
export function matchingExclusions(t){const x=exclusionFeatures(t);if(!x)return [];return EXCLUSION_GROUPS.flatMap((g,i)=>g.side===t.side&&g.conditions.every(([k,op,v])=>Number.isFinite(x[k])&&(op==='<='?x[k]<=v:x[k]>=v))?[i+1]:[]);}
